var root = protobuf.parse(proto, { keepCase: true }).root;
window.mesega = root.lookupType("Data");
var compressed = root.lookupType("uncompressedData");
function decodeMobileData(data) {
    /*
     * Decode exactly what was received.
     * Never hide a malformed packet by
     * deleting bytes from its tail.
     */
    return window.mesega.decode(data);
}

/*
 * Envelopes with contentType != 1 carry the Req zlib-compressed in compressedData
 * (official client: haxe_zip_Uncompress.run, i.e. RFC 1950). Inflate with the
 * browser's DecompressionStream and decode the inner message. Returns a Promise.
 */
/*
 * Pending opcode-130 league requests, oldest first. The official client does not
 * read leagueRequestType in the 131 reply (the server can leave it out, which
 * decodes as 0): the reply answers the request it registered for.
 *   _lmTakePendingLeagueRequest(0, type)  -> queue a sent request
 *   _lmTakePendingLeagueRequest(type)     -> remove that type, return it
 *   _lmTakePendingLeagueRequest()         -> remove and return the oldest (0 if none)
 * Entries older than 30 s were never answered and are dropped.
 */
window._lmPendingLeagueRequests = [];
window._lmTakePendingLeagueRequest = function (type, queueType) {
    var list = window._lmPendingLeagueRequests;
    var now = Date.now();
    while (list.length && now - list[0].at > 30000) list.shift();
    if (queueType) {
        list.push({ type: queueType, at: now });
        return queueType;
    }
    if (type === 1 || type === 2) {
        for (var i = 0; i < list.length; i++) {
            if (list[i].type === type) { list.splice(i, 1); break; }
        }
        return type;
    }
    return list.length ? list.shift().type : 0;
};

window.decodeCompressedMobileData = function (bytes) {
    if (typeof DecompressionStream !== 'function') {
        return Promise.reject(new Error('DecompressionStream not supported'));
    }
    /* zlib (RFC 1950) per the official client; fall back to raw deflate and gzip
     * so an unexpected format is not silently dropped. */
    var formats = ['deflate', 'deflate-raw', 'gzip'];
    var attempt = function (i) {
        var stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream(formats[i]));
        return new Response(stream).arrayBuffer().then(function (buf) {
            return compressed.decode(new Uint8Array(buf));
        }).catch(function (err) {
            if (i + 1 < formats.length) return attempt(i + 1);
            throw err;
        });
    };
    return attempt(0);
};

function encodeProtoVarint(value) {
    var number = Number(value);

    if (
        !Number.isSafeInteger(number) ||
        number < 0
    ) {
        throw new RangeError(
            'Invalid protobuf varint value: ' +
            value
        );
    }

    var bytes = [];

    do {
        var byte = number % 128;

        number =
            Math.floor(number / 128);

        if (number > 0) {
            byte |= 0x80;
        }

        bytes.push(byte);
    } while (number > 0);

    return bytes;
}

function ReqPing() {
    if (
        !legendmod.integrity ||
        !window.core ||
        typeof window.core
            .proxyMobileData !==
            'function'
    ) {
        return;
    }

    /* Not established yet (no 241 key): sendMessage() would drop it anyway. */
    if (legendmod.connectionIntegrity && !legendmod.clientKey) {
        return;
    }

    /*
     * Same values as Delta's working ping: a small pingId and
     * previousRoundtrip = 1. The old random 31-bit previousRoundtrip told
     * the server the last round trip took up to ~24 days.
     */
    var pingId =
        Math.floor(
            Math.random() *
            1000
        );

    var previousRoundtrip =
        1;

    /* agario_proto_Ping: field 1 = pingId, field 2 = previousRoundtrip
     * (agario/mc/agario.js writeTo); they were swapped. */
    var pingPayload = [8]
        .concat(
            encodeProtoVarint(
                pingId
            )
        )
        .concat([16])
        .concat(
            encodeProtoVarint(
                previousRoundtrip
            )
        );

    var uncompressedPayload =
        [8, 30, 242, 1]
            .concat(
                encodeProtoVarint(
                    pingPayload.length
                )
            )
            .concat(pingPayload);

    var packet = [8, 1, 18]
        .concat(
            encodeProtoVarint(
                uncompressedPayload
                    .length
            )
        )
        .concat(
            uncompressedPayload
        );

    window.agarpingstarted =
        Date.now();

    window.core.proxyMobileData(
        new Uint8Array(packet)
    );
}


