/*
 * ═════════════════════════════════════════════════════════════════════════════
 * BOOST BUY / USE
 * ═════════════════════════════════════════════════════════════════════════════
 *
 * BUY:
 *
 *   productId
 *      ↓
 *   GameConfiguration
 *      ↓
 *   exact purchaseId
 *      ↓
 *   existing window.softPurchase()
 *
 *
 * USE:
 *
 *   productId
 *      ↓
 *   existing application.activateBoost()
 *
 *
 * No hardcoded prices.
 * No hardcoded purchase IDs.
 * No hardcoded protobuf byte arrays.
 */

function buyBoost(
    productId
) {
    var info =
        typeof window
            .getAgarBoostInfo ===
            'function'
            ? window
                .getAgarBoostInfo(
                    productId
                )
            : null;


    if (
        !info ||
        !info.purchaseId
    ) {
        console.error(
            '[BOOST] No configured purchase for:',
            productId
        );

        if (
            window.toastr
        ) {
            toastr.error(
                _lmG1tag('game1.tag.boost', 'game1.boost.noPurchaseId')
            );
        }

        return false;
    }


    if (
        typeof window
            .softPurchase !==
            'function'
    ) {
        if (
            window.toastr
        ) {
            toastr.error(
                _lmG1tag('game1.tag.boost', 'game1.boost.noTransport')
            );
        }

        return false;
    }


    return window
        .softPurchase(
            info.purchaseId,
            {
                kind:
                    'boost',

                productId:
                    info.productId,

                purchaseId:
                    info.purchaseId,

                onSuccess:
                    function (
                        response,
                        pendingPurchase
                    ) {
                        /*
                         * productUpdates were already applied by opcode 71
                         * before this callback runs.
                         */
                        if (
                            typeof window
                                .initBoostDropdown ===
                                'function'
                        ) {
                            window
                                .initBoostDropdown(
                                    true
                                );
                        }


                        if (
                            typeof window
                                .syncProfileTabUI ===
                                'function'
                        ) {
                            window
                                .syncProfileTabUI();
                        }


                        /*
                         * Dedicated Shop windows repaint from authoritative state.
                         */
                        try {
                            document.dispatchEvent(
                                new CustomEvent(
                                    'lm-configured-boost-purchased',
                                    {
                                        detail: {
                                            productId:
                                                info.productId,

                                            purchaseId:
                                                info.purchaseId,

                                            response:
                                                response,

                                            pendingPurchase:
                                                pendingPurchase
                                        }
                                    }
                                )
                            );
                        } catch (
                            boostPurchaseEventError
                        ) {
                        }
                    },

                onFailure:
                    function (
                        reason
                    ) {
                        console.warn(
                            '[BOOST] Purchase failed:',
                            productId,
                            reason
                        );
                        if (window._lmPurchaseFailToast) window._lmPurchaseFailToast(_lmG1e(lmT('game1.tag.boost')), reason);
                    }
            }
        );
}


function useBoost(
    productId
) {
    var info =
        typeof window
            .getAgarBoostInfo ===
            'function'
            ? window
                .getAgarBoostInfo(
                    productId
                )
            : null;


    if (!info) {
        console.error(
            '[BOOST] Unknown configured boost:',
            productId
        );

        if (
            window.toastr
        ) {
            toastr.error(
                _lmG1tag('game1.tag.boost', 'game1.boost.unknown')
            );
        }

        return false;
    }


    if (
        window.application &&
        typeof window
            .application
            .activateBoost ===
            'function'
    ) {
        /* a second click before the server answered (opcode 113) sent a second activation
             * and could use up another boost item; the 113 reply clears this */
            var _lmBoostPend = window._lmBoostPending || (window._lmBoostPending = {});
            if (_lmBoostPend[info.productId] && Date.now() - _lmBoostPend[info.productId] < 10000) {
                if (window.toastr) toastr.info(_lmG1tag('game1.tag.boost', 'game1.boost.pending'));
                return false;
            }
            var _lmBoostSent = window.application.activateBoost(info.productId);
            if (_lmBoostSent) _lmBoostPend[info.productId] = Date.now();
            return _lmBoostSent;
    }


    if (
        window.toastr
    ) {
        toastr.error(
            _lmG1tag('game1.tag.boost', 'game1.boost.noActivation')
        );
    }

    return false;
}


/*
 * ═════════════════════════════════════════════════════════════════════════════
 * CONFIGURED BOOST ACTION BRIDGE
 * ═════════════════════════════════════════════════════════════════════════════
 *
 * lm_extended_ui.js must never duplicate:
 *
 *      productId -> purchaseId
 *      softPurchase()
 *      activateBoost()
 *
 * Those jobs already belong to buyBoost()/useBoost().
 *
 * Expose only tiny bridges.
 */

window.buyConfiguredBoost =
    function (
        productId
    ) {
        return buyBoost(
            productId
        );
    };


window.useConfiguredBoost =
    function (
        productId
    ) {
        return useBoost(
            productId
        );
    };


