window.getOfficialAgarXpState = function (
    fallbackLevel,
    fallbackXp,
    fallbackLimit
) {
    /*
     * LEGACY FALLBACK — Hardcoded XP formula.
     *
     * Prefer getAgarXpEntry(level).xpToNextLevel from
     * GameConfiguration when available. This formula is
     * retained only for offline/config-unavailable scenarios.
     *
     * WARNING: This formula says level 1 → 50,
     * but GameConfiguration says level 1 → 35.
     */
    function calculateAgarExp(q) {
        var lvl = Math.max(1, Number(q) || 1);
        if (lvl === 1) return 50;
        if (lvl === 2) return 125;
        if (lvl === 3) return 250;
        if (lvl === 4) return 500;
        var exp = 0;
        for (var i = 1; i <= lvl; i++) {
            exp += i * 100;
        }
        return exp - 500;
    }

    var level =
        Number(fallbackLevel) ||
        Number(window.agarioLEVEL) ||
        1;

    var currentXp =
        Number(fallbackXp);

    if (!isFinite(currentXp) || currentXp < 0) {
        currentXp = Number(window.agarioXP) || 0;
    }

    var totalXp = 0;

    /*
     * Primary source: Agar.io's live user and XP model.
     * This is the same source used by the official client.
     */
    try {
        /* Expanding Land: Core.user is the official agar.io account (logged in on its
         * own), so its level/XP replaced the Expanding Land values passed in. */
        if (
            !_isExpandingLandClient(window.legendmod) &&
            window.Core &&
            Core.user &&
            Core.user.userInfo
        ) {
            var officialLevel =
                Number(
                    Core.user.userInfo.level
                );

            var officialXp =
                Number(
                    Core.user.userInfo.xp
                );

            if (
                isFinite(officialLevel) &&
                officialLevel > 0
            ) {
                level = officialLevel;
            }

            if (
                isFinite(officialXp) &&
                officialXp >= 0
            ) {
                currentXp = officialXp;
            }
        }

        if (
            window.Core &&
            Core.models &&
            Core.models.xpModel &&
            typeof Core.models.xpModel
                .getMaxXpForLevel ===
            'function'
        ) {
            var officialLimit =
                Number(
                    Core.models.xpModel
                        .getMaxXpForLevel(
                            level
                        )
                );

            if (
                isFinite(officialLimit) &&
                officialLimit > 0
            ) {
                totalXp = officialLimit;
            }
        }
    } catch (officialXpError) {
        console.warn(
            '[XP] Could not read the live Agar.io XP model:',
            officialXpError
        );
    }

    /*
     * GameConfiguration table source.
     *
     * Uses getAgarXpEntry(level) which reads the correct
     * field: xpToNextLevel (from "Gameplay - XP to Level").
     */
    if (!(totalXp > 0)) {
        try {
            var xpEntry = window.getAgarXpEntry
                ? window.getAgarXpEntry(level)
                : null;
            if (xpEntry) {
                var gcXp = Number(
                    xpEntry.xpToNextLevel
                );
                if (
                    isFinite(gcXp) &&
                    gcXp > 0
                ) {
                    totalXp = gcXp;
                }
            }
        } catch (gcError) { }
    }

    /*
     * Secondary source: Agar.io's cached official account data.
     */
    if (!(totalXp > 0)) {
        try {
            var storedUserInfo =
                window.agarApp &&
                    agarApp.storageInfo &&
                    agarApp.storageInfo.userInfo
                    ? agarApp.storageInfo.userInfo
                    : null;

            if (storedUserInfo) {
                var storedLimit =
                    Number(
                        storedUserInfo.xpNeeded
                    );

                if (
                    isFinite(storedLimit) &&
                    storedLimit > 0
                ) {
                    totalXp = storedLimit;
                }
            }
        } catch (storedXpError) {
            console.warn(
                '[XP] Could not read cached Agar.io XP data:',
                storedXpError
            );
        }
    }

    /*
     * Legend Mod application fallback
     */
    if (!(totalXp > 0)) {
        var lmApp =
            window.application ||
            window.legendmod ||
            window.agarApp ||
            null;

        if (
            lmApp &&
            typeof lmApp.agarExp ===
            'function'
        ) {
            var calculatedLimit =
                Number(
                    lmApp.agarExp(
                        level
                    )
                );

            if (
                isFinite(calculatedLimit) &&
                calculatedLimit > 0
            ) {
                totalXp = calculatedLimit;
            }
        }
    }

    /*
     * Supplied limit fallback (only if valid and >= currentXp)
     */
    if (!(totalXp > 0)) {
        var suppliedLimit =
            Number(fallbackLimit);

        if (
            isFinite(suppliedLimit) &&
            suppliedLimit > 0 &&
            suppliedLimit >= currentXp
        ) {
            totalXp = suppliedLimit;
        }
    }

    /*
     * LAST-RESORT FALLBACK — Algorithmic XP limit.
     *
     * Only runs if GameConfiguration, Core.models.xpModel,
     * cached account data, application.agarExp(), AND the
     * supplied fallback limit ALL failed to produce a value.
     */
    if (!(totalXp > 0) || totalXp < currentXp || (level > 5 && totalXp === 1000)) {
        totalXp = calculateAgarExp(level);
    }

    var percent =
        totalXp > 0
            ? Math.max(
                0,
                Math.min(
                    100,
                    currentXp * 100 /
                    totalXp
                )
            )
            : 0;

    return {
        level: level,
        currentXp: currentXp,
        totalXp: totalXp,
        percent: percent
    };
};

window.updateOfficialXpPanel = function (
    level,
    expPercent
) {
    var xpState =
        window.getOfficialAgarXpState(
            level,
            window.agarioXP,
            window.agarioNextXP
        );

    var lvlVal =
        xpState.level;

    var currentXp =
        Math.floor(
            xpState.currentXp
        );

    var totalXp =
        Math.floor(
            xpState.totalXp
        );

    var resolvedPercent =
        expPercent !== undefined &&
            expPercent !== null
            ? Number(expPercent)
            : xpState.percent;

    resolvedPercent =
        Math.max(
            0,
            Math.min(
                100,
                isFinite(resolvedPercent)
                    ? resolvedPercent
                    : 0
            )
        );

    window.agarioLEVEL =
        lvlVal;

    window.agarioXP =
        currentXp;

    window.agarioNextXP =
        totalXp;

    /*
     * Legend Mod's compact level panel.
     */
    var officialXpPanel =
        $('#exp-bar');

    officialXpPanel
        .find(
            '.progress-bar-striped, .progress-bar'
        )
        .css({
            transition: '5s',
            width:
                resolvedPercent +
                '%'
        });

    var star3 =
        officialXpPanel.find(
            '.progress-bar-star3'
        );

    if (star3.length > 0) {
        star3.text(lvlVal);
    } else {
        officialXpPanel
            .find(
                '.progress-bar-text'
            )
            .html(
                '★★ <strong class="progress-bar-star3">' +
                lvlVal +
                '</strong>'
            );
    }

    /*
     * Original Agar.io XP bar inside #profile.
     * Do not replace this text with the level number.
     */
    var profilePanels =
        $('#profile .agario-profile-panel')
            .not('#exp-bar');

    profilePanels
        .find(
            '.progress-bar-star'
        )
        .text(lvlVal);

    if (totalXp > 0) {
        profilePanels
            .find(
                '.progress-bar-text'
            )
            .text(
                currentXp +
                '/' +
                totalXp +
                ' XP'
            );
    }

    profilePanels
        .find(
            '.progress-bar, .progress-bar-striped'
        )
        .not(
            '.progress-bar-striped2'
        )
        .css(
            'width',
            resolvedPercent +
            '%'
        );
};

window.updateLegendXpPanel = function () {
    var lmScoreVal = window.LMscore || 0;
    var legendXpPanel = $('.progress-bar-striped2').closest('#exp-bar');

    /* Only target .progress-bar-striped2 — not the generic .progress-bar
     * class which also exists on the left panel's bar element. */
    legendXpPanel.find('.progress-bar-striped2').css({
        "transition": "5s",
        "width": Math.max(0, Math.min(100, lmScoreVal)) + "%"
    });

    var star2 = legendXpPanel.find('.progress-bar-star2');
    if (star2.length > 0) {
        star2.text(lmScoreVal);
    } else {
        legendXpPanel.find('.progress-bar-text').html('★★★ <strong class="progress-bar-star2">' + lmScoreVal + '</strong>');
    }
};

function setLevelProgressBar() {
    window.updateOfficialXpPanel(window.agarioLEVEL);
    window.updateLegendXpPanel();
}

function resetLevelProgressBar() {
    var officialXpPanel = $('#exp-bar').eq(0);
    var legendXpPanel = $('.progress-bar-striped2').closest('#exp-bar');
    officialXpPanel.find('.progress-bar-striped').css({
        "transition": "5s",
        "width": "0%"
    });
    legendXpPanel.find('.progress-bar-striped2').css({
        "transition": "5s",
        "width": "0%"
    });
}
