//bots

window.SERVER_HOST = 'browser' // 'browser' (or empty): browser bots in a Web Worker; else the address of a bot server, e.g. ws://localhost:1337 (start.bat)
//window.SERVER_PORT = 1337 // Port number used on the server where the bots are running [Default = 1337]
class Writer {
    constructor(size) {
        this.dataView = new DataView(new ArrayBuffer(size))
        this.byteOffset = 0
    }
    writeUint8(value) {
        this.dataView.setUint8(this.byteOffset++, value)
    }
    writeInt32(value) {
        this.dataView.setInt32(this.byteOffset, value, true)
        this.byteOffset += 4
    }
    writeUint32(value) {
        this.dataView.setUint32(this.byteOffset, value, true)
        this.byteOffset += 4
    }
    writeString(string) {
        for (let i = 0; i < string.length; i++) this.writeUint8(string.charCodeAt(i))
        this.writeUint8(0)
    }
}
window.buffers = {
    startBots(url, protocolVersion, clientVersion, userStatus, botsName, botsAmount) {
        const writer = new Writer(13 + url.length + botsName.length)
        writer.writeUint8(0)
        writer.writeString(url)
        writer.writeUint32(protocolVersion)
        writer.writeUint32(clientVersion)
        writer.writeUint8(Number(userStatus))
        writer.writeString(botsName)
        writer.writeUint8(botsAmount)
        return writer.dataView.buffer
    },
    sendMode(nick) {
        const writer = new Writer(3 + nick.length)
        writer.writeUint8(7)
        writer.writeUint8(1)
        writer.writeString(nick)
        return writer.dataView.buffer
    },
    captchatoken(x) {
        const writer = new Writer(2 + x.length)
        //const writer = new Writer(x.length)
        writer.writeUint8(7)
        writer.writeString(x)
        return writer.dataView.buffer
    },
    mousePosition(x, y) {
        const writer = new Writer(9)
        writer.writeUint8(6)
        writer.writeInt32(x)
        writer.writeInt32(y)
        return writer.dataView.buffer
    },
    /* [10, u8 n, n x (i32 x, i32 y, u32 mass)]: the player's ghost cells, centred on the map and
       in canonical units like the mouse (scale: 1 when left out), so each bot can find its own map
       orientation on FFA/EXP. */
    ghostRef(cells, offsetX, offsetY, scaleX, scaleY) {
        const n = Math.min(cells.length, 10)
        const writer = new Writer(2 + n * 12)
        writer.writeUint8(10)
        writer.writeUint8(n)
        for (let i = 0; i < n; i++) {
            writer.writeInt32(~~((cells[i].rawX - offsetX) * (scaleX || 1)))
            writer.writeInt32(~~((cells[i].rawY - offsetY) * (scaleY || 1)))
            writer.writeUint32(cells[i].mass >>> 0)
        }
        return writer.dataView.buffer
    },
    captchabots(x) {
        const writer = new Writer(5)
        writer.writeUint8(8)
        writer.writeInt32(x)
        return writer.dataView.buffer
    }
}
/* Browser bots: the bot server's own code (ExampleScripts/agario-bots2/botcore.js, the file server.js
   runs) in a Web Worker of this page, so no bot server is needed and the game's thread only posts the
   control messages. It looks like the bot server's WebSocket to connectionBots: readyState, send,
   close, onopen/onmessage/onclose, the same binary messages both ways. Start (or Fill lobby) loads
   the code; a worker runs from that Start until the session ends (message 2), Stop while connecting,
   or the page closing. Its bots join the game server with this page's origin, spawn with token '0'
   like the player, and only wait when the game server asks for a captcha (no tokens). */
class LMBotsWorkerSocket {
    constructor(src) {
        this.readyState = 0
        this.binaryType = 'arraybuffer'
        this.onopen = this.onmessage = this.onclose = null
        this._worker = null
        this._url = null
        var self = this
        this._unload = function () { self._end(false) }
        window.addEventListener('pagehide', this._unload)
        fetch(src).then(function (r) {
            if (!r.ok) throw new Error('HTTP ' + r.status)
            return r.text()
        }).then(function (code) {
            if (self.readyState !== 0) return
            self._url = URL.createObjectURL(new Blob([code + '\n;LMBotCore.runWorker(self);\n'], { type: 'text/javascript' }))
            self.readyState = 1
            if (self.onopen) self.onopen({})
            self._status()
        }).catch(function (e) {
            console.warn('[LM] Browser bots cannot load:', e)
            self._end(false)
        })
    }
    send(data) {
        if (this.readyState !== 1) return
        var op = typeof data === 'string' ? -1 : new Uint8Array(data)[0]
        if (!this._worker) {
            /* idle: only Start runs a worker; Stop answers like a bot server without a session */
            if (op === 1) return this._deliver(new Uint8Array([2]).buffer)
            if (op !== 0) return
            var self = this, w = this._worker = new Worker(this._url)
            w.onmessage = function (e) {
                if (self._worker !== w || !(e.data instanceof ArrayBuffer)) return
                /* message 2: the session ended and the worker closed its bots: the worker goes */
                if (new Uint8Array(e.data)[0] === 2) self._stopWorker(false)
                self._deliver(e.data)
                if (!self._worker && self.readyState === 1) self._status()
            }
            w.onerror = function (e) {
                if (e && e.preventDefault) e.preventDefault()
                console.warn('[LM] Browser bots stopped:', e && e.message)
                if (self._worker === w) self._end(false)
            }
        }
        this._worker.postMessage(data)
    }
    close() { this._end(true) }
    _deliver(buffer) {
        if (this.readyState === 1 && this.onmessage) this.onmessage({ data: buffer })
    }
    /* idle: no bot connected or spawned (a bot server sends this every second) */
    _status() { this._deliver(new Uint8Array([4, 0, 0]).buffer) }
    /* polite: the worker first closes its bots' game connections, then it is terminated */
    _stopWorker(polite) {
        var w = this._worker
        this._worker = null
        if (!w) return
        w.onmessage = w.onerror = null
        if (!polite) return w.terminate()
        try { w.postMessage('close') } catch (e) { }
        setTimeout(function () { w.terminate() }, 300)
    }
    _end(polite) {
        if (this.readyState === 3) return
        this.readyState = 3
        window.removeEventListener('pagehide', this._unload)
        this._stopWorker(polite)
        if (this._url) { var url = this._url; this._url = null; setTimeout(function () { URL.revokeObjectURL(url) }, 1000) }
        var self = this
        setTimeout(function () { if (self.onclose) self.onclose({ code: 1000 }) }, 0)
    }
}
window.LMBotsWorkerSocket = LMBotsWorkerSocket
/* The connection to the bots: the browser worker or a bot server. There is no Connect button:
   Start and Fill lobby call ensure(), which connects when needed and runs their action again
   once the connection is open (pending). Stop while connecting cancels it (cancel()). */
window.connectionBots = {
    ws: null,
    /* browser bots (Web Worker) for an empty Bots address or "browser", else a bot server */
    inBrowser: false,
    /* the action waiting for the connection: 'start' (Start bots), 'fill' (Fill lobby) or null */
    pending: null,
    /* the current socket has opened (a close before that is a failed connection) */
    opened: false,
    isBrowserHost(host) {
        host = host == null ? '' : String(host).trim().toLowerCase()
        return host === '' || host === 'browser'
    },
    hostKey(host) {
        return this.isBrowserHost(host) ? 'browser' : String(host).trim()
    },
    /* Stop was sent and its end (message 2) has not come yet: the bot core keeps the old session
       for about 2 s and drops a start sent meanwhile. 5 s at most, so a bot server that never
       answers cannot hold Start / Fill lobby back. */
    stopping() {
        var t = window.userBots.stopSentAt
        return !!t && Date.now() - t < 5000
    },
    /* the Bots address field can be opened (the bots panel and its button are shown) */
    addressEditable() {
        var app = window.application
        return !!(app && typeof app._lmQuickBotsShown === 'function' && app._lmQuickBotsShown())
    },
    /* run a Start / Fill lobby that waited for the connection or for the previous bots to stop */
    runAction(action) {
        var run = action === 'start' ? window._lmBotsStart : action === 'fill' ? window._lmBrFill : null
        if (typeof run === 'function') setTimeout(function () { run() }, 0)
    },
    connect() {
        /* A second click while the socket is still connecting opened a second socket,
           so onopen/onclose ran twice (false "Disconnected"). */
        var old = this.ws
        if (old && (old.readyState === WebSocket.CONNECTING || old.readyState === WebSocket.OPEN)) return
        if (old) {
            old.onopen = old.onmessage = old.onclose = null
            try { old.close() } catch (e) { }
        }
        this.inBrowser = this.isBrowserHost(window.SERVER_HOST)
        this.host = this.hostKey(window.SERVER_HOST)
        this.opened = false
        var ws
        try {
            ws = this.inBrowser ? new window.LMBotsWorkerSocket('https://www.legendmod.ml/ExampleScripts/agario-bots2/botcore.js?v=' + (window.OgVer || '')) : new WebSocket(`${window.SERVER_HOST}`)
        } catch (e) {
            /* not a WebSocket address (e.g. no ws://): a failed connection */
            this.ws = null
            this.onclose({})
            return
        }
        this.ws = ws
        var self = this
        var current = function (fn) {
            return function (e) { if (self.ws === ws) return fn.call(self, e) }
        }
        ws.binaryType = 'arraybuffer'
        ws.onopen = current(this.onopen)
        ws.onmessage = current(this.onmessage)
        ws.onclose = current(this.onclose)
        this.setStatus('game1.bots.connecting', '#FF9800')
    },
    /* true: the connection is open, do the action now. false: it is connecting (started here when
       needed) and onopen runs the action ('start' or 'fill') again; the last action asked wins. */
    ensure(action) {
        var open = this.ws
        if (open && open.readyState === WebSocket.OPEN) {
            /* a changed Bots address takes effect on the next Start / Fill lobby (no bots running):
               the open connection to the old one used to stay until a reload */
            if (this.host === this.hostKey(window.SERVER_HOST) || window.userBots.startedBots || window.userBots.startSent || this.stopping()) return true
            this.ws = null
            open.onopen = open.onmessage = open.onclose = null
            try { open.close() } catch (e) { }
        }
        this.pending = action
        this.connect()
        return false
    },
    /* Stop while connecting: forget the waiting action and close the socket that is still
       connecting (quietly: no "closed" notice). An open connection stays open. */
    cancel() {
        this.pending = null
        var ws = this.ws
        if (!ws || ws.readyState !== WebSocket.CONNECTING) return false
        this.ws = null
        ws.onopen = ws.onmessage = ws.onclose = null
        try { ws.close() } catch (e) { }
        this.setStatus('game1.bots.disconnected', '#DA0A00')
        this.buttons(false)
        return true
    },
    send(buffer) {
        if (this.ws && this.ws.readyState === WebSocket.OPEN) this.ws.send(buffer)
    },
    setStatus(key, color) {
        var el = document.getElementById('userStatus')
        if (!el) return
        this.live = false
        el.style.color = color
        _lmG1set(el, key)
    },
    /* Message 4 also carries the bots waiting for a captcha and the bots the game server refused
       (bot servers before that send only 3 bytes): then the status line says so instead of Connected. */
    sessionStatus(waiting, refused) {
        var el = document.getElementById('userStatus')
        if (!el) return
        var text = function (key, en, n) { var s = lmT(key, [n]); return !s || s === key ? en.replace('{0}', n) : s }
        var line = waiting ? text('pkg.bots.captchaWaiting', 'Waiting for a captcha: {0}', waiting)
            : refused ? text('pkg.bots.refusedCount', 'Refused by the game server: {0}', refused) : null
        if (!line) {
            if (this.live) this.setStatus('game1.bots.connected', '#00C02E')
            return
        }
        this.live = true
        if (el.removeAttribute) el.removeAttribute('data-i18n')
        el.style.color = '#FF9800'
        if (el.textContent !== line) el.textContent = line
    },
    /* Start or Stop: busy = Stop (connecting for a Start, bots starting or running), else Start */
    buttons(busy) {
        var start = document.getElementById('startBots'), stop = document.getElementById('stopBots')
        if (!start || !stop) return
        start.disabled = !!busy
        start.style.display = busy ? 'none' : 'inline'
        stop.disabled = !busy
        stop.style.display = busy ? 'inline' : 'none'
        _lmG1set(stop, 'game1.bots.stop')
    },
    onopen() {
        this.opened = true
        this.setStatus('game1.bots.connected', '#00C02E')
        /* Start / Fill lobby pressed while not connected: continue it now (one click). */
        var action = this.pending
        this.pending = null
        this.runAction(action)
    },
    onmessage(message) {
        const dataView = new DataView(message.data)
        switch (dataView.getUint8(0)) {
            case 0:
                this.buttons(true)
                window.userBots.startedBots = true
                /* The player may have spawned or died since Start; the server only knew the state at Start. */
                this.send(new Uint8Array([5, window.userBots.isAlive ? 1 : 0]).buffer)
                break
            case 1:
                document.getElementById('stopBots').disabled = true
                _lmG1set(document.getElementById('stopBots'), 'game1.bots.stopping')
                break
            case 2: {
                /* the previous bots have stopped: a Start / Fill lobby pressed meanwhile runs now */
                var next = window.userBots.stopSentAt ? this.pending : null
                window.userBots.stopSentAt = 0
                if (next) this.pending = null
                document.getElementById('botsAI').style.color = '#DA0A00'
                document.getElementById('botsAI').innerText = lmT('game1.bots.disabled')
                this.buttons(false)
                window.userBots.startedBots = false
                window.userBots.startSent = false
                window.userBots.spawned = 0
                window.bots.ai = false
                if (typeof window._brResetFill === 'function') window._brResetFill()
                if (typeof window._brUpdateSection === 'function') window._brUpdateSection()
                if (next) this.runAction(next)
                /* the session stopped by a server change has ended: the bots may follow now (not when
                   a Start / Fill lobby pressed meanwhile just ran: that one replaces the follow) */
                else if (typeof window._lmBotsTryResume === 'function') window._lmBotsTryResume()
                break
            }
            case 3:
                toastr.info(lmT('game1.bots.captchaIp'))
                break
            case 4:
                window.userBots.spawned = dataView.getUint8(2)
                $('#botCount').html(`${dataView.getUint8(1)}/${dataView.getUint8(2)}/${window.userBots.sessionAmount || window.bots.amount}`)
                this.sessionStatus(dataView.byteLength > 3 ? dataView.getUint8(3) : 0, dataView.byteLength > 4 ? dataView.getUint8(4) : 0)
                /* our bots in the Battle Royale lobby count */
                if (typeof window._brUpdateSection === 'function') window._brUpdateSection()
                break
            case 9:
                // Bot positions from server (absolute world coords) — receive gracefully
                break
            case 10:
                toastr.info('<b>[' + Premadeletter123 + ']:</b> ' + lmT('game1.bots.closing'));
                break
            case 12:
                /* The game server asks the bots for a captcha: they take no tokens, they wait and
                   try again with '0' (after 5 minutes without a new captcha request). */
                toastr.warning('<b>[' + Premadeletter123 + ']:</b> ' + _lmTH('game1.bots.captchaNeeded', 'The game server asks the bots for a captcha.') + ' ' + _lmTH('game1.bots.captchaWait', 'The bots wait and try again in a few minutes.'))
                break
            case 13:
                /* The bot server cannot join this game server (not an agar.io arena). */
                toastr.info('<b>[' + Premadeletter123 + ']:</b> ' + _lmTH('game1.bots.agarOnly', 'The bots work on agar.io servers only.'))
                break
            case 14: {
                /* The game server refused every bot (each lost 6 connections in a row before it could
                   spawn): the session ends (1 and 2 follow). u16: the last close code. */
                var code = message.data.byteLength >= 3 ? dataView.getUint16(1, true) : 0
                toastr.warning('<b>[' + Premadeletter123 + ']:</b> ' + _lmTH('pkg.bots.refused', 'The game server refused the bots’ connections. The bots stopped.') + (code ? ' (' + code + ')' : ''))
                break
            }
        }
    },
    onclose(event) {
        var failed = !this.opened
        var action = this.pending
        this.pending = null
        window.userBots.stopSentAt = 0
        this.setStatus('game1.bots.disconnected', '#DA0A00')
        document.getElementById('botsAI').style.color = '#DA0A00'
        document.getElementById('botsAI').innerText = lmT('game1.bots.disabled')
        this.buttons(false)
        window.userBots.startedBots = false
        window.userBots.startSent = false
        window.userBots.spawned = 0
        window.bots.ai = false
        // Clean up Battle Royale fill state on bot server disconnect
        if (typeof window._brStopFilling === 'function') window._brStopFilling()
        if (typeof window._brUpdateSection === 'function') window._brUpdateSection()
        /* A bot server address saved earlier that does not answer while the Bots address field
           cannot be opened (the bots panel is hidden): nobody could change it, so every Start /
           Fill lobby failed. Forget it and use the bots in this browser, for this click too. */
        if (failed && !this.inBrowser && !this.addressEditable()) {
            window.SERVER_HOST = window.bots.remoteIP = 'browser'
            try { localStorage.removeItem('localstoredBotsRemoteIP') } catch (e) { }
            var field = document.getElementById('botsRemoteIP')
            if (field) field.value = 'browser'
            if (action) { this.pending = action; this.connect() }
            return
        }
        /* never opened: the browser bots' code did not load, or no bot server at that address */
        if (failed) toastr.warning('<b>[' + Premadeletter123 + ']:</b> ' + _lmTH('game1.bots.connectFailed', 'The bots cannot connect. Check the address: browser, or your bot server (ws://localhost:1337).'))
        else toastr.warning("<b>[" + Premadeletter123 + "]:</b> " + lmT('game1.bots.wsClosed'))
    }
}
/* Stop the bot session, also while it is still starting (Start sent, no bot spawned yet)
   or still connecting for a Start / Fill lobby (cancelled).
   serverChange (LM.connect, a new game server: mode or region switch, reconnect after a drop, a
   version change, a party): bots started with Start (also still starting or connecting; not a
   Battle Royale fill) are remembered and start again on the new server once it is ready
   (_lmBotsTryResume). Any other stop (the Stop button) forgets them. */
window._lmBotsStop = function (serverChange) {
    var ub = window.userBots, cb = window.connectionBots
    if (serverChange) {
        if ((ub.startedBots || ub.startSent || cb.pending === 'start') && !window._brFilling) {
            window._lmBotsForget()
            var p = window._lmBotsResume = { timer: null }
            /* the new server is not ready in 30 s (no server found, no map border): say why they stopped */
            p.timer = setTimeout(function () { if (window._lmBotsResume === p) window._lmBotsCannotFollow() }, 30000)
        }
        /* the new server is not an agar.io arena: the bots cannot join it */
        if (window._lmBotsResume && window.legendmod && !window.legendmod.integrity) window._lmBotsCannotFollow()
    } else window._lmBotsForget()
    window.connectionBots.cancel()
    if ((window.userBots.startedBots || window.userBots.startSent) && window.connectionBots.ws && window.connectionBots.ws.readyState === WebSocket.OPEN) {
        window.connectionBots.send(new Uint8Array([1]).buffer)
        /* the bots stop about 2 s later (message 2): a Start / Fill lobby meanwhile waits for it */
        window.userBots.stopSentAt = Date.now()
    }
    window.userBots.startSent = false
    /* the bots leave: they are not counted in this server's lobby any more */
    window.userBots.spawned = 0
    if (typeof window._brUpdateSection === 'function') window._brUpdateSection()
}
/* Bots waiting to follow the player to the new game server ({ timer }), else null */
window._lmBotsResume = null
window._lmBotsForget = function () {
    var p = window._lmBotsResume
    window._lmBotsResume = null
    if (p && p.timer) clearTimeout(p.timer)
}
window._lmBotsCannotFollow = function () {
    window._lmBotsForget()
    toastr.warning('<b>[' + Premadeletter123 + ']:</b> ' + _lmTH('pkg.bots.serverChanged', 'The bots stopped because the game server changed.'))
}
/* Run by the new server's map border (its handshake is done, the game is ready) and by the end of
   the old session (message 2): Start again once both happened. true when it started. */
window._lmBotsTryResume = function () {
    var lm = window.legendmod, ub = window.userBots, cb = window.connectionBots
    if (!window._lmBotsResume || !lm) return false
    /* the old session is still ending, or a Start / Fill lobby is already on its way */
    if (ub.startedBots || ub.startSent || cb.pending) return false
    if (!lm.ws || !lm.integrity || !(ub.offsetFixed && ub.offsetSeq === (lm._connectSeq || 0))) return false
    window._lmBotsForget()
    if (typeof window._lmBotsStart === 'function') window._lmBotsStart()
    return true
}
