    /*
     * ═════════════════════════════════════════════════════════════════════
     * GAMECONFIGURATION VISUAL / CLIENT-DEFAULT INDEXES
     * ═════════════════════════════════════════════════════════════════════
     */


    /*
     * Small local helper for the many:
     *
     *      { key: "...", value: ... }
     *
     * sections.
     *
     * Store the entire source row rather than only row.value so future
     * GameConfiguration versions may add useful metadata without requiring
     * another structural migration.
     */
    function indexKeyValueSection(
        sectionName,
        destination
    ) {
        var sectionRows =
            rows(
                sectionName
            );

        for (
            var sectionIndex = 0;
            sectionIndex <
                sectionRows.length;
            sectionIndex++
        ) {
            var sectionRow =
                sectionRows[
                    sectionIndex
                ];

            if (
                !sectionRow ||
                sectionRow.key ===
                    undefined ||
                sectionRow.key ===
                    null
            ) {
                continue;
            }

            var sectionKey =
                String(
                    sectionRow.key
                ).trim();

            if (!sectionKey) {
                continue;
            }

            destination[
                sectionKey
            ] =
                sectionRow;
        }
    }


