/*
 * Convenience helpers for UI prediction.
 *
 * They answer:
 *
 *      "According to the currently loaded client configuration,
 *       would this mass normally satisfy the configured threshold?"
 *
 * They DO NOT authorize an action and they do not replace the server.
 */
window.canAgarConfigShootMass =
    function (
        mass,
        mode
    ) {
        var threshold =
            window
                .getAgarGameplayCapabilities(
                    mode
                )
                .minMassToShoot;

        if (
            threshold ===
                null
        ) {
            return null;
        }

        var currentMass =
            Number(
                mass
            );

        if (
            !Number.isFinite(
                currentMass
            )
        ) {
            return null;
        }

        return (
            currentMass >=
            threshold
        );
    };


window.canAgarConfigSplitMass =
    function (
        mass,
        mode
    ) {
        var threshold =
            window
                .getAgarGameplayCapabilities(
                    mode
                )
                .minMassToSplit;

        if (
            threshold ===
                null
        ) {
            return null;
        }

        var currentMass =
            Number(
                mass
            );

        if (
            !Number.isFinite(
                currentMass
            )
        ) {
            return null;
        }

        return (
            currentMass >=
            threshold
        );
    };


