            css += ':root{--lm-tc:' + _lmCssVal(defaultSettings.menuTextColor, '#ffffff') + ';--lm-tc2:' + _lmCssVal(defaultSettings.menuTextColor2, '#8096a7') + '}';
            this.addCustomCSS('menuTextColorCSS', css);
