                ';--lm-btn3:' + cv('btn3Color', '#8d5fe6') + ';--lm-btn3b:' + cv('btn3Color2', '#814ee3') +
                ';--lm-btn4:' + cv('btn4Color', '#bf00aa') + ';--lm-btn4b:' + cv('btn4Color2', '#a80096') + '}';
