                var tagStr = ogarcopythelb.clanTag || '';
                if (onlyIfSet && !tagStr) return;
                /* Real UTF-8 (was masked to 7 bits, so "Ⓜ" became "B"). The server keeps
                 * 15 bytes; cut on a character boundary so no partial character is sent. */
