        sendMessage(message) {
            /* delt.io (Delta's legacy protocol): send only the opcodes it reads
             * (spawn, spectate, mouse, split, Q, eject, ping/pong, handshake);
             * never chat 99, agar.io 102 tokens or LM/Expanding Land opcodes. */
            if (this.serverType === 'deltio' && message && message.buffer) {
                var _dlOp = new Uint8Array(message.buffer, message.byteOffset || 0, 1)[0];
                if ([0, 1, 16, 17, 18, 19, 21, 22, 226, 227, 254, 255].indexOf(_dlOp) === -1) return;
            }
            if (this.connectionOpened && this.connectionIntegrity) {
                if (!this.clientKey) {
                    return;
                }
                message = this.shiftMessage(message, this.clientKey);
                this.clientKey = this.shiftKey(this.clientKey);
            }
            /*jimboy3100
            if (window.LMdebug){
                window.tempoo = new window.buffer.Buffer(message.buffer)
                if (window.tempoo[0]==102){ 
                    window.tempoo2 = new window.buffer.Buffer(window.tempoo.buffer)	
                    console.log(window.tempoo2)
                }					
            }*/
            this.sendBuffer(message);
        },
        sendAction(action) {

            if (!this.isSocketOpen()) {
                return;
            }
            /* Replay Studio: split moments (17 split; 28/26/27 double/triple/quad on private servers)
             * and feeding (21, at most 4/s: mass lost by feeding is not a "big mass loss" bookmark) */
            if (window._lmRecLive && this === window.legendmod) {
                if (action === 17 || (action >= 26 && action <= 28)) window._lmRecEv('p', action === 17 ? 1 : action === 28 ? 2 : action === 26 ? 3 : 4);
                else if (action === 21 && !(Date.now() - (this._lmRecFeedAt || 0) < 250)) { this._lmRecFeedAt = Date.now(); window._lmRecEv('f', 0); }
            }
            // Sigmally: encode opcode through shuffle table
            if (this.serverType === 'sigmally' && this.sigOpcodeMap) {
                var sv = new ArrayBuffer(1);
                new Uint8Array(sv)[0] = this.sigOpcodeMap[action];
                this.socket.send(sv);
                return;
            }
            // Garix: split (17) and eject (21) require tabID
            if (this.serverType === 'garix' && (action === 17 || action === 21)) {
                var gv = this.createView(3);
                gv.setUint8(0, action);
                gv.setUint16(1, this.garixTabID1 || 0, true);
                this.sendBuffer(gv);
                return;
            }
            const view = this.createView(1);
            view.setUint8(0, action);
            this.sendMessage(view);
        },
        sendSpectate() {
            if (this._lmSpecLb != null) { this._lmSpecLb = null; this._lmSpecLbHud(); }
            if (this._lmSpecCell) this._lmSpecCellStop();
            this.isSpectateEnabled = true;
            this._lmSpawnRetrySeq = (this._lmSpawnRetrySeq || 0) + 1; /* cancels a pending spawn retry */
            /* Expanding Land leaves World Spectate on opcode 1 and 18 (client.c on_spectate /
             * on_spectate_toggle): stop the World Spectate mouse pan here too, or the camera
             * kept panning away from the followed player. */
            this._isWorldSpectating = false;
            this._worldSpecPanX = 0;
            this._worldSpecPanY = 0;
            if (this.serverType === 'senpa') {
                this._senpaSpectate = true;
                // Mode byte of the cursor packet: 2 = follow top (Delta default), 1 = free roam.
                this._senpaSpecMode = 2;
                this.isFreeSpectate = false;
                return; // Senpa spectate is toggled by mouse position opcode
            }
            // Sigmally has no plain spectate opcode: use free spectate (qe[18] + qe[19]), as Delta does.
            if (this.serverType === 'sigmally') {
                if (this.sigOpcodeMap && !this.isFreeSpectate) this.sendFreeSpectate();
                return;
            }
            /* opcode 1 is the follow camera: the server ends free roam with it (Expanding Land
             * on_spectate, Ogar servers), so the next Q starts free spectate again */
            this.isFreeSpectate = false;
            this.sendAction(1);
        },
        /* Spawning ends every spectate mode (follow, free spectate, World Spectate) on every
         * protocol. A free spectate flag left on after the spawn was the wrong way round after the
         * next death: Q there started free spectate on the server while the flag went off, and
         * Watch killer and the leaderboard / click follows judged by the stale flag. */
        _lmSpawnEndsSpectate() {
            this.isSpectateEnabled = false;
            this.isFreeSpectate = false;
            this._isWorldSpectating = false;
            this._worldSpecPanX = 0;
            this._worldSpecPanY = 0;
        },
        sendFreeSpectate() {
            if (this._lmSpecLb != null) { this._lmSpecLb = null; this._lmSpecLbHud(); }
            if (this._lmSpecCell) this._lmSpecCellStop();
            this._lmSpawnRetrySeq = (this._lmSpawnRetrySeq || 0) + 1; /* cancels a pending spawn retry, like sendSpectate */
            /* Expanding Land: Q in World Spectate goes to the follow camera (client.c
             * on_spectate_toggle: full map -> grouped); elsewhere it toggles free roam */
            var _lmFromWorld = !!(this._isWorldSpectating && this.isLegendWorld);
            this.isFreeSpectate = _lmFromWorld ? false : !this.isFreeSpectate;
            if (_lmFromWorld) this.isSpectateEnabled = true;
            this._isWorldSpectating = false;
            this._worldSpecPanX = 0;
            this._worldSpecPanY = 0;
            // Senpa has no free-spectate opcode: switch the cursor packet's mode byte instead.
            if (this.serverType === 'senpa') {
                this._senpaSpectate = true;
                this.isSpectateEnabled = true;
                this._senpaSpecMode = this.isFreeSpectate ? 1 : 2;
                return;
            }
            // Sigmally: free spectate requires two opcodes: qe[18] + qe[19] with delay
            if (this.serverType === 'sigmally' && this.sigOpcodeMap) {
                this.sendAction(18);
                var self = this;
                setTimeout(function () { self.sendAction(19); }, 100);
                return;
            }
            this.sendAction(18);
        },
