        /*
         * LEGACY FALLBACK — Hardcoded XP formula.
         *
         * Prefer getAgarXpEntry(level).xpToNextLevel from
         * GameConfiguration when available. This method is
         * retained only for offline/config-unavailable scenarios.
         */
        agarExp(q) {
            var s = {};
            var i = 0,
                exp = 0;
            for (i = 1; i <= q; i++) {
                exp += i * 100;
            }
            exp -= 500;
            if (q <= 4) {
                exp = q === 1 ? 50 : q === 2 ? 125 : q === 3 ? 250 : 500;
            }
            return exp
        },
        handleSubmessage(message) {
            var e = 0;

            try {
                message =
                    this.decompressMessage(message);
            } catch (error) {
                /* diagnostics: a compressed frame rejected (most world updates come compressed) */
                if (this._lmND) { this._lmND.zBad++; this._lmND.badAt = this._lmND.zAt = performance.now(); }
                console.warn(
                    "[LM] Rejected invalid compressed packet:",
                    error
                );
                return;
            }

            if (!message || message.length < 1) {
                if (this._lmND) { this._lmND.zBad++; this._lmND.badAt = this._lmND.zAt = performance.now(); }
                console.warn(
                    "[LM] Rejected empty decompressed packet"
                );
                return;
            }

            switch (message.readUInt8(e++)) {
                case 16:
                    /* Same as uncompressed opcode 16: agar.io sends most cell updates
                     * here, so the dead main client's viewport must be dropped too. */
                    var _lmMbHeldZ = !!(window.mainPlayerDeadMbActive && this._lmKeepMainSuppressed());
                    if (this._lmND) this._lmWuRx(_lmMbHeldZ ? 1 : 0);
                    if (_lmMbHeldZ) {
                        if (this._lmCellIdentity) this._lmCellIdentityScan(message, e);
                        break;
                    }
                    var _tPkt = performance.now();
                    this.updateCells(message, e);
                    this.countPps();
                    if (window.clientProfiler) window.clientProfiler.recordPacket(performance.now() - _tPkt);
                    break;
                case 64:
                    /* a cut-short border is dropped whole instead of half-stored */
                    if (message.length < e + 32) break;
                    this._lmOnServerBorder(message.readDoubleLE(e), message.readDoubleLE(e + 8), message.readDoubleLE(e + 16), message.readDoubleLE(e + 24), 'compressed');
                    break;
                default:
                    console.log('\x1b[32m%s\x1b[34m%s\x1b[0m', consoleMsgLM, ' Unknown sub opcode:', message.readUInt8(0));
            }
        },
