                    document.createElement(
                        'canvas'
                    );

                backgroundCanvas.id =
                    'legendmod-render-background';

                backgroundCanvas.style.cssText =
                    'position:absolute;' +
                    'top:0;' +
                    'left:0;' +
                    'pointer-events:none;' +
                    'background:transparent;';

