                LM.mapMinX != null
                    ? LM.mapMinX
                    : -7071;

            var mapMinY =
                LM.mapMinY != null
                    ? LM.mapMinY
                    : -7071;

            var mapMaxX =
                LM.mapMaxX != null
                    ? LM.mapMaxX
                    : 7071;

