function setGUIEvents() {
    document.getElementById('botsAmount').addEventListener('keypress', e => {
        e.preventDefault()
    })
    var storedbotsRemoteIP = localStorage.getItem("localstoredBotsRemoteIP");
    /* never saved (or emptied): browser bots; a saved bot server address keeps working */
    if (storedbotsRemoteIP == null || storedbotsRemoteIP === "") {
        storedbotsRemoteIP = "browser";
    }
    window.bots.remoteIP = storedbotsRemoteIP
    window.SERVER_HOST = storedbotsRemoteIP;
    $('#botsRemoteIP').val(storedbotsRemoteIP)
    var storedbotsname = localStorage.getItem("localStoredBotsName");
    if (storedbotsname == null || storedbotsname === "") {
        storedbotsname = "Legendmod|ml";
    }
    window.bots.nameLM = storedbotsname;
    $('#botsNameLM').val(storedbotsname)
    var storedbotsamount = localStorage.getItem("localStoredBotsAmount");
    if (storedbotsamount == null || storedbotsamount === "") {
        storedbotsamount = 50;

    }
    /* localStorage returns a string; "50" + 20 would concatenate to "5020". */
    window.bots.amount = Number(storedbotsamount) || 50;
    $('#botsAmount').val(window.bots.amount)
    document.getElementById('botsRemoteIP').addEventListener('change', function () {
        window.bots.remoteIP = this.value
        localStorage.setItem('localstoredBotsRemoteIP', window.bots.remoteIP)
        window.SERVER_HOST = window.bots.remoteIP
    })
    document.getElementById('botsNameLM').addEventListener('change', function () {
        document.getElementById('botsNameLM').value = document.getElementById('botsNameLM').value.replace(/[^\x20-\x7E]/g, '');
        window.bots.nameLM = this.value
        localStorage.setItem('localStoredBotsName', window.bots.nameLM)
    })
    document.getElementById('botsAmount').addEventListener('change', function () {
        /* Update first, then save the new value (it used to save the previous one). */
        window.bots.amount = Number(this.value)
        localStorage.setItem('localStoredBotsAmount', window.bots.amount)
    })
    /* Start: one click. Checks first, then connects to the bots when needed (browser worker or
       the bot server of the address field: connectionBots.ensure) and starts once connected
       (onopen runs botsStart again). Double clicks: the Start button is hidden from the first
       click (Stop instead) and a Start already waiting for the connection is not repeated. */
    function botsStart() {
        var cb = window.connectionBots
        var refuse = function (html) {
            toastr.info('<b>[' + Premadeletter123 + ']:</b> ' + html)
            cb.buttons(false)
        }
        if (window.userBots.startedBots && !cb.stopping() || window.userBots.startSent) {
            toastr.info('<b>[' + Premadeletter123 + ']:</b> ' + _lmTH('game2.brBotsRunning', 'Bots already running'))
            return
        }
        if (cb.pending === 'start') return
        if (!legendmod.ws || !window.EnvConfig.configVersion || !window.master.clientVersion) return refuse(_lmTH('game2.brNoGameServer', 'Not connected to game server'))
        /* The bots join agar.io game servers only (they need its connection key); every agar.io mode. */
        if (!legendmod.integrity) return refuse(_lmTH('game1.bots.agarOnly', 'The bots work on agar.io servers only.'))
        if (!window.bots.amount) return refuse(lmT('game2.botsAmount'))
        if (typeof window._brResetFill === 'function') window._brResetFill()
        cb.buttons(true)
        /* the previous bots are still stopping: start when they have (message 2) */
        if (cb.stopping()) { cb.pending = 'start'; return }
        if (!cb.ensure('start')) return
        /* Clamp this session only: the saved amount stays what the user typed. */
        var _lmBotsN = Math.max(1, Math.min(window.bots.amount, 197 - legendmod.leaderboard.length));
        window.userBots.startSent = true
        /* this session replaces bots still waiting to follow from the previous server */
        if (typeof window._lmBotsForget === 'function') window._lmBotsForget()
        window.userBots.sessionAmount = _lmBotsN
        cb.send(window.buffers.startBots(legendmod.ws, window.gameBots.protocolVersion, window.gameBots.clientVersion, window.userBots.isAlive, window.unescape(window.encodeURIComponent(window.bots.nameLM)), _lmBotsN))
        if (legendmod.gameMode != ":party") cb.send(window.buffers.sendMode(window.unescape(window.encodeURIComponent(ogarcopythelb.nick))))
    }
    window._lmBotsStart = botsStart
    document.getElementById('startBots').addEventListener('click', () => botsStart())
    document.getElementById('stopBots').addEventListener('click', () => {
        window._lmBotsStop()
    })

    /* "On this server": the players of the game server. agar.io sends the whole leaderboard (every
       player in the arena, opcode 53), so it is counted like the leaderboard footer: a name that
       appears more than twice is a group of bots. Battle Royale: the lobby's player count (178).
       No capacity: agar.io sends none, so none is made up. Other servers: their board is a top 10 only. */
    function botsServerPlayersText() {
        var lm = window.legendmod
        if (!lm || !lm.ws) return lmT('game1.bots.waiting')
        if (!lm.integrity) return '-'
        var count = function (n, one, many) { return lmT(n === 1 ? one : many, [n]) }
        if (lm.gameMode === ':battleroyale') {
            var brN = lm.battleRoyale && lm.battleRoyale.players
            return brN ? count(brN, 'game2.sbPlayer', 'game2.sbPlayers') : lmT('game1.bots.waiting')
        }
        var lb = lm.leaderboard || []
        if (!lb.length) return lmT('game1.bots.waiting')
        var seen = Object.create(null), bots = 0, i
        for (i = 0; i < lb.length; i++) { var k = '#' + (lb[i] && lb[i].nick); seen[k] = (seen[k] || 0) + 1 }
        for (var name in seen) if (seen[name] > 2) bots += seen[name]
        return count(lb.length - bots, 'game2.sbPlayer', 'game2.sbPlayers') + (bots > 0 ? ' · ' + count(bots, 'game2.sbBot', 'game2.sbBots') : '')
    }
    window._lmBotsServerPlayersText = botsServerPlayersText
    /* No timer: written when the panel opens (applyQuickPanels), on every leaderboard and Battle
       Royale lobby update of the main connection (handleLeaderboard) and on a server switch.
       While the panel is closed nothing is done (its flag equals what is shown). */
    window._lmBotsServerPlayersRefresh = function () {
        if (!defaultmapsettings.showQuickBots) return
        var el = document.getElementById('botsServerPlayers')
        if (!el) return
        var text = botsServerPlayersText()
        if (el.textContent !== text) el.textContent = text
    }

    /* ─── Battle Royale lobby fill ─── */
    window._brFilling = false

    /* No timer: runs on every Battle Royale lobby packet of the main connection (176 countdown,
       177 battle begun, 178 lobby players, 180 end), when our bots' count changes (bot messages
       2 and 4, Stop, the bot connection closing) and on a server or mode switch (syncQuickPanels). */
    function brUpdateSection() {
        var sec = document.getElementById('brBotsSection')
        if (!sec) return
        var isBR = legendmod.gameMode === ':battleroyale'
        sec.style.display = isBR ? '' : 'none'
        if (!isBR) { brStopFilling(); return }
        var br = legendmod.battleRoyale
        if (window._brFilling && br.started) {
            /* the battle has begun (177): the bots of the fill leave; during the countdown (176) they stay so it is not cancelled */
            toastr.success('<b>[' + Premadeletter123 + ']:</b> ' + _lmTH('game2.brGameStarted', 'BR game started!'))
            brStopFilling()
        }
        var status = document.getElementById('brLobbyStatus')
        if (!status) return
        /* 178 sends the players of the lobby before the battle too; 176 = countdown, 177 = battle begun. */
        var text
        if (br.players || br.started || br.countdown) {
            var stateStr = br.started ? _lmTH('game2.brStateInGame', 'In game') : br.countdown ? _lmTH('game2.brStateStarting', 'Starting') : _lmTH('game2.brStateWaiting', 'Waiting')
            /* our bots in the lobby: the spawned bots of this session (message 4), never more than the lobby */
            var ours = window.userBots.startedBots || window.userBots.startSent ? Math.min(window.userBots.spawned || 0, br.players || 0) : 0
            text = ours > 0
                ? _lmTH('game2.brPlayersBots', 'Players: {0} ({1} real + {2} bots) | State: {3}').replace('{0}', br.players).replace('{1}', br.players - ours).replace('{2}', ours).replace('{3}', stateStr)
                : _lmTH('game2.brPlayers', 'Players: {0} | State: {1}').replace('{0}', br.players).replace('{1}', stateStr)
        } else {
            text = _lmTH('game2.brNotInLobby', 'Not in lobby yet')
        }
        /* a live line: a language change must not put the first "Waiting for lobby data" back
           over it (data-i18n); the language change rewrites it here instead (LMi18n.onChange) */
        if (status.removeAttribute) status.removeAttribute('data-i18n')
        if (status.textContent !== text) status.textContent = text
    }

    /* Forget a fill (its buttons) without touching the bots: after Stop bots, a manual
       Start or the end of the session, so the end of a fill can never stop bots started by hand. */
    function brResetFill() {
        if (window.connectionBots.pending === 'fill') window.connectionBots.pending = null
        if (!window._brFilling) return false
        window._brFilling = false
        var fillBtn = document.getElementById('brFillLobby')
        var stopBtn = document.getElementById('brStopFill')
        if (fillBtn) fillBtn.style.display = ''
        if (stopBtn) stopBtn.style.display = 'none'
        return true
    }
    function brStopFilling() {
        // Stop the bots of this fill, also while they are still starting (no-op when no fill runs)
        if (brResetFill()) window._lmBotsStop()
    }
    window._brStopFilling = brStopFilling
    window._brResetFill = brResetFill

    /* Fill lobby: one click. Like Start, it connects through connectionBots.ensure('fill') and
       runs again once connected (onopen); every check is made again then. */
    function brFill() {
        var cb = window.connectionBots
        if (cb.pending === 'fill') return
        if (legendmod.gameMode !== ':battleroyale') {
            toastr.warning('<b>[' + Premadeletter123 + ']:</b> ' + _lmTH('game2.brModeRequired', 'Battle Royale mode required'))
            return
        }
        if (!legendmod.integrity) {
            toastr.info('<b>[' + Premadeletter123 + ']:</b> ' + _lmTH('game1.bots.agarOnly', 'The bots work on agar.io servers only.'))
            return
        }
        if (!legendmod.ws || !window.EnvConfig.configVersion || !window.master.clientVersion) {
            toastr.warning('<b>[' + Premadeletter123 + ']:</b> ' + _lmTH('game2.brNoGameServer', 'Not connected to game server'))
            return
        }
        if (window.userBots.startedBots && !cb.stopping() || window.userBots.startSent || cb.pending === 'start') {
            toastr.info('<b>[' + Premadeletter123 + ']:</b> ' + _lmTH('game2.brBotsRunning', 'Bots already running'))
            return
        }

        var br = legendmod.battleRoyale
        // Only while the lobby waits: not during the countdown (176) or the battle (177)
        if (br.started || br.countdown) {
            toastr.warning('<b>[' + Premadeletter123 + ']:</b> ' + _lmTH('game2.brNotWaiting', 'Lobby is not in waiting state'))
            return
        }
        if (!br.players) {
            toastr.info('<b>[' + Premadeletter123 + ']:</b> ' + _lmTH('game2.brWaitingData', 'Waiting for lobby data…'))
            return
        }
        // Lobby size: the fewest players a countdown started with here (learned), else 15
        var currentPlayers = br.players || 0
        var brRequired = 15
        try { var _lmBrL = parseInt(localStorage.getItem('lmBrStartPlayers'), 10); if (_lmBrL >= 2 && _lmBrL <= 200) brRequired = _lmBrL } catch (e) { }
        var needed = brRequired - currentPlayers
        if (needed <= 0) {
            toastr.info('<b>[' + Premadeletter123 + ']:</b> ' + _lmTH('game2.brLobbyFull', 'Lobby already has {0} players').replace('{0}', currentPlayers))
            return
        }
        needed = Math.min(needed, 190)
        /* the previous bots are still stopping (Stop fill, the battle began, a server switch):
           the bot core would drop this start, so it fills when they have stopped (message 2) */
        if (cb.stopping()) {
            cb.pending = 'fill'
            toastr.info('<b>[' + Premadeletter123 + ']:</b> ' + lmT('game1.bots.stopping'))
            return
        }
        if (!cb.ensure('fill')) {
            toastr.info('<b>[' + Premadeletter123 + ']:</b> ' + _lmTH('game2.brConnecting', 'Connecting to bot server…'))
            return
        }
        /* This session only: the user's own bot amount setting is not changed. */
        window.userBots.startSent = true
        if (typeof window._lmBotsForget === 'function') window._lmBotsForget()
        window.userBots.sessionAmount = needed
        cb.buttons(true)
        cb.send(window.buffers.startBots(
            legendmod.ws,
            window.gameBots.protocolVersion,
            window.gameBots.clientVersion,
            window.userBots.isAlive,
            window.unescape(window.encodeURIComponent(window.bots.nameLM)),
            needed
        ))
        cb.send(window.buffers.sendMode(window.unescape(window.encodeURIComponent(ogarcopythelb.nick))))

        window._brFilling = true
        document.getElementById('brFillLobby').style.display = 'none'
        document.getElementById('brStopFill').style.display = ''
        toastr.info('<b>[' + Premadeletter123 + ']:</b> ' + _lmTH('game2.brFilling', 'Filling BR lobby with {0} bots…').replace('{0}', needed))

        /* No watcher timer: the fill stops when the battle begins or the mode changes (brUpdateSection,
           run by the lobby packets and the server switch) and when the bot connection closes (onclose). */
        brUpdateSection()
    }
    window._lmBrFill = brFill
    window._brUpdateSection = brUpdateSection
    /* no timer rewrites the lobby line: a language change does */
    if (window.LMi18n && typeof window.LMi18n.onChange === 'function') window.LMi18n.onChange(function () { brUpdateSection() })
    document.getElementById('brFillLobby').addEventListener('click', () => brFill())

    document.getElementById('brStopFill').addEventListener('click', brStopFilling)
    brUpdateSection()
}


function minimapCell(envId, cb, i, s) {
    this.id = envId;
    this.nick = cb;
    this.skinID = i;
    this.skinURL = s;
    this.lbgpi = -1; //Sonia4

    /*
     * Raw target position (set by server updates).
     * These are the "ground truth" coordinates.
     */
    this.x = 0;
    this.y = 0;

    /*
     * Animated display position (what we actually render).
     * Lerps toward x/y each frame for smooth movement.
     */
    this.lastX = 0;
    this.lastY = 0;

    /*
     * Flag: false until first real position arrives.
     * Prevents the initial lerp-from-origin jump.
     */
    this.positionInitialized = false;

    this.mass = 0;
    this.clanTag = "";
    this.color = null;
    this.customColor = defaultSettings.miniMapTeammatesColor;
    this.alive = false;
    this.updateTime = null;
    this.pi2 = 2 * Math.PI;

    /*
     * Nick canvas cache.
     * Stores a pre-rendered offscreen canvas of the nick text
     * so we don't call fillText/strokeText every frame.
     */
    this._nickCache = null;     /* offscreen canvas */
    this._nickCacheKey = null;  /* cache invalidation key */

    this.setColor = function (i, inRevIdx) {
        /*
         * Colors come from other players over the team relay and are later
         * inserted into HTML style attributes (teamboard, colored chat nicks).
         * Accept only #rgb / #rrggbb so a crafted value cannot break out.
         */
        var isHexColor = function (value) {
            return typeof value === 'string' && /^#(?:[0-9a-f]{3}|[0-9a-f]{6})$/i.test(value);
        };
        /* the white of a teammate that sent no colour is for the minimap and team list only:
         * _lmColorSent says the colour is the teammate's own, so only then it colours cells */
        if (isHexColor(i)) this._lmColorSent = true;
        if (i === '#000000' && this.color !== i && window._lmColorDiag) window._lmColorDiag('teammate sent black', null, { conn: 'chat relay', nick: this.nick, color: i, src: 'team colour (chat relay)' });
        this.color = isHexColor(i) ? i : (this.color || '#ffffff');
        if (isHexColor(inRevIdx) && 7 === inRevIdx.length) {
            this.customColor = inRevIdx;
        }
    };

    /*
     * Set raw target position.
     * On the very first update, snap animated position
     * to the target immediately (no lerp from 0,0).
     */
    this.setPosition = function (px, py) {
        this.x = px;
        this.y = py;
        if (!this.positionInitialized) {
            this.lastX = px;
            this.lastY = py;
            this.positionInitialized = true;
        }
    };

    /*
     * Build a cache key from all settings that affect
     * the nick text appearance.  If anything changes
     * the cached canvas is invalidated.
     */
    this._buildNickCacheKey = function () {
        return (
            this.nick + '|' +
            defaultSettings.miniMapNickFontWeight + '|' +
            defaultSettings.miniMapNickSize + '|' +
            defaultSettings.miniMapNickFontFamily + '|' +
            defaultSettings.miniMapNickStrokeSize + '|' +
            defaultSettings.miniMapNickStrokeColor + '|' +
            defaultSettings.miniMapNickColor
        );
    };

    /*
     * Render the nick text to an offscreen canvas.
     * Called only when the cache key changes.
     */
    this._renderNickCache = function () {
        var key = this._buildNickCacheKey();
        if (this._nickCacheKey === key && this._nickCache) {
            return;
        }
        this._nickCacheKey = key;

        var font =
            defaultSettings.miniMapNickFontWeight +
            ' ' +
            defaultSettings.miniMapNickSize +
            'px ' +
            defaultSettings.miniMapNickFontFamily;

        /* Measure text width on a temporary context */
        if (!minimapCell._measureCtx) {
            var mc = document.createElement('canvas');
            mc.width = 1;
            mc.height = 1;
            minimapCell._measureCtx = mc.getContext('2d');
        }
        minimapCell._measureCtx.font = font;
        var metrics = minimapCell._measureCtx.measureText(this.nick);
        var textWidth = Math.ceil(metrics.width);
        var strokePad = defaultSettings.miniMapNickStrokeSize || 0;
        var fontSize = defaultSettings.miniMapNickSize || 10;

        var cw = textWidth + strokePad * 2 + 4;
        var ch = fontSize + strokePad * 2 + 4;

        if (!this._nickCache) {
            this._nickCache = document.createElement('canvas');
        }
        this._nickCache.width = cw;
        this._nickCache.height = ch;
        var ctx = this._nickCache.getContext('2d');

        ctx.font = font;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';

        var cx = cw / 2;
        var cy = ch / 2;

        if (strokePad > 0) {
            ctx.lineWidth = strokePad;
            ctx.strokeStyle = defaultSettings.miniMapNickStrokeColor;
            ctx.strokeText(this.nick, cx, cy);
        }

        ctx.fillStyle = defaultSettings.miniMapNickColor;
        ctx.fillText(this.nick, cx, cy);
    };

    this.drawPosition = function (options, margin, mult, startcode, endcode, value) {
        if (!(!this.alive || startcode && endcode && this.id != endcode)) {

            /*
             * Smooth interpolation: lerp animated position
             * toward raw target at ~97% per frame.
             */
            /* 1/30 per 33 ms tick trailed about a second behind (positions arrive once a
             * second) and slid across the map after a respawn: 20% per tick, and jump when the
             * teammate moved more than 2000 units (respawn / teleport). */
            var _lmMdx = this.x - this.lastX, _lmMdy = this.y - this.lastY;
            if (!isFinite(_lmMdx) || !isFinite(_lmMdy) || _lmMdx * _lmMdx + _lmMdy * _lmMdy > 4000000) {
                this.lastX = this.x;
                this.lastY = this.y;
            } else {
                this.lastX += _lmMdx * 0.2;
                this.lastY += _lmMdy * 0.2;
            }

            var w = (this.lastX + margin) * mult;
            var h = (this.lastY + margin) * mult;
            /* Cull against the real minimap size (the slider allows 120-400 px). */
            var _lmMapSize = window.legendmod && window.legendmod.mapSize;
            var _lmLimit = _lmMapSize > 0 ? mult * _lmMapSize + 10 : 170;
            if (w < -10 || w > _lmLimit || h < -10 || h > _lmLimit) return;

            /*
             * Draw nick from cached offscreen canvas.
             */
            if (this.nick.length > 0) {
                this._renderNickCache();
                if (this._nickCache && this._nickCache.width > 0) {
                    var nickY = h - (2 * defaultSettings.miniMapTeammatesSize + 2);
                    options.drawImage(
                        this._nickCache,
                        w - this._nickCache.width / 2,
                        nickY - this._nickCache.height / 2
                    );
                }
            }

            /* Draw teammate dot */
            options.beginPath();
            options.arc(w, h, defaultSettings.miniMapTeammatesSize, 0, this.pi2, false);
            options.closePath();
            if (defaultmapsettings.oneColoredTeammates) {
                options.fillStyle = defaultSettings.miniMapTeammatesColor;
            } else {
                options.fillStyle = value;
            }
            options.fill();
        }
    };
}


